<?php
namespace App\Http\Controllers;
use App\Models\Unlock; use App\Models\UnlockParticipation; use App\Models\Partner; use App\Models\Location; use App\Models\Benefit; use App\Models\Experience; use App\Services\UnlockStatusService; use Illuminate\Http\Request; use Illuminate\Support\Str; use Inertia\Inertia;
class AdminUnlockController extends Controller { public function index(){return Inertia::render('admin/unlocks/index',['unlocks'=>Unlock::with('partner')->withCount(['participations as committed_count'=>fn($q)=>$q->where('status',UnlockParticipation::COMMITTED)])->latest()->get()]);} public function form(?Unlock $unlock=null){return Inertia::render('admin/unlocks/form',['unlock'=>$unlock?->load('locations'),'partners'=>Partner::orderBy('name')->get(['id','name']),'locations'=>Location::orderBy('name')->get(['id','name']),'benefits'=>Benefit::orderBy('title')->get(['id','title']),'experiences'=>Experience::orderBy('title')->get(['id','title'])]);} public function save(Request $r,?Unlock $unlock=null){$d=$r->validate($this->rules());$unlock??=new Unlock(['created_by_user_id'=>$r->user()->id]);if($unlock->participations()->where('status',UnlockParticipation::COMMITTED)->exists())abort_if(collect($d)->only(['minimum_commitments','maximum_capacity','free_user_offer','member_offer','commitment_deadline','terms','jp_deposit'])->filter(fn($v,$k)=>$unlock->{$k}!=$v)->isNotEmpty(),422,'Admin operation required after commitments.');$unlock->fill($d);$unlock->slug??=Str::slug($d['title']).'-'.Str::lower(Str::random(5));$unlock->save();$unlock->locations()->sync($d['location_ids']??[]);return to_route('admin.unlocks.index');} public function transition(Request $r,Unlock $unlock,UnlockStatusService $s){$d=$r->validate(['status'=>'required|in:APPROVED,SCHEDULED,ACTIVE,CANCELLED,REJECTED','reason'=>'nullable|string']);$s->transition($unlock,$d['status'],$r->user(),$d['reason']??null);return back();} private function rules():array{return ['title'=>'required|string|max:255','short_description'=>'nullable|string','description'=>'nullable|string','terms'=>'nullable|string','partner_id'=>'nullable|exists:partners,id','origin'=>'required|in:JAKAWI,PARTNER','type'=>'required|in:BENEFIT,PRICE,EXPERIENCE,SECRET','minimum_commitments'=>'required|integer|min:1','maximum_capacity'=>'nullable|integer|min:1|gte:minimum_commitments','starts_at'=>'nullable|date','commitment_deadline'=>'nullable|date','free_user_eligible'=>'boolean','member_eligible'=>'boolean','free_user_offer'=>'nullable|string','member_offer'=>'nullable|string','jp_deposit'=>'nullable|integer|min:0','jp_completion_bonus'=>'nullable|integer|min:0','linked_benefit_id'=>'nullable|exists:benefits,id','linked_experience_id'=>'nullable|exists:experiences,id','featured'=>'boolean','secret_mode'=>'boolean','hide_partner_until_unlock'=>'boolean','hide_exact_offer_until_unlock'=>'boolean','hide_location_until_unlock'=>'boolean','location_ids'=>'array','location_ids.*'=>'exists:locations,id'];}}
